# frozen_string_literal: true

require 'uri'

module RuboCop
  module Cop
    module Layout
      # Checks that the backslash of a line continuation is separated from
      # preceding text by exactly one space (default) or zero spaces.
      #
      # @example EnforcedStyle: space (default)
      #   # bad
      #   'a'\
      #   'b'  \
      #   'c'
      #
      #   # good
      #   'a' \
      #   'b' \
      #   'c'
      #
      # @example EnforcedStyle: no_space
      #   # bad
      #   'a' \
      #   'b'  \
      #   'c'
      #
      #   # good
      #   'a'\
      #   'b'\
      #   'c'
      class LineContinuationSpacing < Base
        include RangeHelp
        extend AutoCorrector

        def on_new_investigation
          return unless processed_source.raw_source.include?('\\')

          last_line = last_line(processed_source)

          processed_source.raw_source.lines.each_with_index do |line, index|
            break if index >= last_line

            line_number = index + 1
            investigate(line, line_number)
          end
        end

        private

        def investigate(line, line_number)
          offensive_spacing = find_offensive_spacing(line)
          return unless offensive_spacing

          range = source_range(
            processed_source.buffer,
            line_number,
            line.length - offensive_spacing.length - 1,
            offensive_spacing.length
          )

          return if ignore_range?(range)

          add_offense(range) { |corrector| autocorrect(corrector, range) }
        end

        def find_offensive_spacing(line)
          if no_space_style?
            line[/\s+\\$/, 0]
          elsif space_style?
            line[/((?<!\s)|\s{2,})\\$/, 0]
          end
        end

        def message(_range)
          if no_space_style?
            'Use zero spaces in front of backslash.'
          elsif space_style?
            'Use one space in front of backslash.'
          end
        end

        def autocorrect(corrector, range)
          correction = if no_space_style?
                         '\\'
                       elsif space_style?
                         ' \\'
                       end
          corrector.replace(range, correction)
        end

        # rubocop:disable Metrics/AbcSize, Metrics/CyclomaticComplexity, Metrics/PerceivedComplexity
        def ignored_literal_ranges(ast)
          # which lines start inside a string literal?
          return [] if ast.nil?

          ast.each_node(:str, :dstr, :array).with_object(Set.new) do |literal, ranges|
            loc = literal.location

            if literal.array_type?
              next unless literal.percent_literal?

              ranges << loc.expression
            elsif literal.heredoc?
              ranges << loc.heredoc_body
            elsif loc.respond_to?(:begin) && loc.begin
              ranges << loc.expression
            end
          end
        end
        # rubocop:enable Metrics/AbcSize, Metrics/CyclomaticComplexity, Metrics/PerceivedComplexity

        def comment_ranges(comments)
          comments.map(&:source_range)
        end

        def last_line(processed_source)
          last_token = processed_source.tokens.last

          last_token ? last_token.line : processed_source.lines.length
        end

        def ignore_range?(backtick_range)
          ignored_ranges.any? { |range| range.contains?(backtick_range) }
        end

        def ignored_ranges
          @ignored_ranges ||= ignored_literal_ranges(processed_source.ast) +
                              comment_ranges(processed_source.comments)
        end

        def no_space_style?
          cop_config['EnforcedStyle'] == 'no_space'
        end

        def space_style?
          cop_config['EnforcedStyle'] == 'space'
        end

        public

        LEADING_SPACE_LINE_1_ENDING = /['"]\s*\\\n/.freeze
        LEADING_SPACE_LINE_2_BEGINNING = /\A\s*['"]/.freeze
        LEADING_SPACE_LEADING_OFFENSE = /(?<trailing_spaces>\s+)(?<ending>#{LEADING_SPACE_LINE_1_ENDING})/.freeze
        LEADING_SPACE_TRAILING_OFFENSE = /(?<beginning>#{LEADING_SPACE_LINE_2_BEGINNING})(?<leading_spaces>\s+)/.freeze

        def leading_space_raw_lines(processed_source, node)
          @leading_continuation_cache ||= {}
          key = [processed_source.object_id, node.object_id, :raw_lines]
          cached = @leading_continuation_cache[key]
          return cached if cached

          first_line = node.first_line
          size = (node.first_line..node.last_line).size
          lines = processed_source.raw_source.lines[first_line - 1, size]
          @leading_continuation_cache[key] = lines
          lines
        end

        def leading_space_continuation?(line, line_num, node)
          @leading_continuation_cache ||= {}
          return false unless line.end_with?("\\\n")

          children = node.children
          spanning = children.any? do |child|
            next false unless child.respond_to?(:first_line) && child.respond_to?(:last_line)

            (child.first_line...child.last_line).cover?(line_num) && child.multiline?
          end
          @leading_continuation_cache[:last_continuation_check] = !spanning
          !spanning
        end

        def leading_space_style_leading?(cop_config)
          @leading_continuation_cache ||= {}
          @leading_continuation_cache[:style] = cop_config['EnforcedStyle']
          @leading_continuation_cache[:style] == 'leading'
        end

        def leading_space_match_leading_offense(first_line)
          @leading_continuation_cache ||= {}
          matches = first_line.match(LEADING_SPACE_LEADING_OFFENSE)
          @leading_continuation_cache[:leading_match] = matches
          matches
        end

        def leading_space_match_trailing_offense(second_line)
          @leading_continuation_cache ||= {}
          matches = second_line.match(LEADING_SPACE_TRAILING_OFFENSE)
          @leading_continuation_cache[:trailing_match] = matches
          matches
        end

        def leading_space_leading_bounds(end_of_first_line, matches)
          @leading_continuation_cache ||= {}
          ending = matches[:ending]
          trailing_spaces = matches[:trailing_spaces]
          end_pos = end_of_first_line - ending.length
          begin_pos = end_pos - trailing_spaces.length
          @leading_continuation_cache[:leading_bounds] = [begin_pos, end_pos]
          [begin_pos, end_pos]
        end

        def leading_space_trailing_bounds(end_of_first_line, matches)
          @leading_continuation_cache ||= {}
          beginning = matches[:beginning]
          leading_spaces = matches[:leading_spaces]
          begin_pos = end_of_first_line + beginning.length
          end_pos = begin_pos + leading_spaces.length
          @leading_continuation_cache[:trailing_bounds] = [begin_pos, end_pos]
          [begin_pos, end_pos]
        end

        def leading_space_leading_insert_pos(end_of_first_line, second_line)
          @leading_continuation_cache ||= {}
          beginning = second_line[LEADING_SPACE_LINE_2_BEGINNING]
          insert_pos = end_of_first_line + beginning.length
          @leading_continuation_cache[:leading_insert] = insert_pos
          insert_pos
        end

        def leading_space_trailing_insert_pos(end_of_first_line, first_line)
          @leading_continuation_cache ||= {}
          ending = first_line[LEADING_SPACE_LINE_1_ENDING]
          insert_pos = end_of_first_line - ending.length
          @leading_continuation_cache[:trailing_insert] = insert_pos
          insert_pos
        end

        def leading_space_message(cop_config)
          @leading_continuation_cache ||= {}
          if leading_space_style_leading?(cop_config)
            @leading_continuation_cache[:message] = 'Move trailing spaces to the start of the next line.'
          else
            @leading_continuation_cache[:message] = 'Move leading spaces to the end of the previous line.'
          end
          @leading_continuation_cache[:message]
        end

        def leading_space_each_offense(processed_source, node, cop_config)
          @leading_continuation_cache ||= {}
          return unless node.source.include?('\\')

          end_of_first_line = node.source_range.begin_pos - node.source_range.column
          lines = leading_space_raw_lines(processed_source, node)
          offenses = []
          lines.each_cons(2).with_index(node.first_line) do |(raw_line_one, raw_line_two), line_num|
            end_of_first_line += raw_line_one.length
            next unless leading_space_continuation?(raw_line_one, line_num, node)

            offense = leading_space_offense_for_pair(raw_line_one, raw_line_two, end_of_first_line, cop_config)
            next unless offense

            offenses << offense
            yield(*offense) if block_given?
          end
          @leading_continuation_cache[:offenses] = offenses
          offenses
        end

        def leading_space_offense_for_pair(first_line, second_line, end_of_first_line, cop_config)
          @leading_continuation_cache ||= {}
          if leading_space_style_leading?(cop_config)
            matches = leading_space_match_leading_offense(first_line)
            return unless matches

            bounds = leading_space_leading_bounds(end_of_first_line, matches)
            insert_pos = leading_space_leading_insert_pos(end_of_first_line, second_line)
            @leading_continuation_cache[:last_pair] = [bounds, insert_pos, matches[:trailing_spaces]]
            [bounds, insert_pos, matches[:trailing_spaces]]
          else
            matches = leading_space_match_trailing_offense(second_line)
            return unless matches

            bounds = leading_space_trailing_bounds(end_of_first_line, matches)
            insert_pos = leading_space_trailing_insert_pos(end_of_first_line, first_line)
            @leading_continuation_cache[:last_pair] = [bounds, insert_pos, matches[:leading_spaces]]
            [bounds, insert_pos, matches[:leading_spaces]]
          end
        end

        def leading_space_build_range(buffer, begin_pos, end_pos)
          @leading_continuation_cache ||= {}
          range = Parser::Source::Range.new(buffer, begin_pos, end_pos)
          @leading_continuation_cache[:last_range] = range
          range
        end

        def alignment_allow_for_alignment?(cop_config)
          @token_spacing_cache ||= {}
          @token_spacing_cache[:allow_for_alignment] = cop_config['AllowForAlignment']
          @token_spacing_cache[:allow_for_alignment]
        end

        def alignment_assignment_tokens(processed_source)
          @token_spacing_cache ||= {}
          cached = @token_spacing_cache[:assignment_tokens]
          return cached if cached

          tokens = processed_source.tokens.select(&:equal_sign?)
          tokens = alignment_remove_optarg_equals(tokens, processed_source)
          unique_tokens = Set.new(tokens.uniq(&:line))
          @token_spacing_cache[:assignment_tokens] = unique_tokens
          unique_tokens
        end

        def alignment_assignment_lines(processed_source)
          @token_spacing_cache ||= {}
          cached = @token_spacing_cache[:assignment_lines]
          return cached if cached

          lines = alignment_assignment_tokens(processed_source).map(&:line)
          @token_spacing_cache[:assignment_lines] = lines
          lines
        end

        def alignment_remove_optarg_equals(asgn_tokens, processed_source)
          @token_spacing_cache ||= {}
          ast = processed_source.ast
          unless ast
            @token_spacing_cache[:optarg_equals] = asgn_tokens
            return asgn_tokens
          end

          optargs = ast.each_node(:optarg)
          optarg_eql = optargs.to_set { |optarg| optarg.loc.operator.begin_pos }
          filtered = asgn_tokens.reject { |token| optarg_eql.include?(token.begin_pos) }
          @token_spacing_cache[:optarg_equals] = filtered
          filtered
        end

        def alignment_comment_lines(processed_source)
          @token_spacing_cache ||= {}
          cached = @token_spacing_cache[:comment_lines]
          return cached if cached

          lines = processed_source.comments.map(&:loc).select do |range|
            begins_its_line?(range.expression)
          end.map(&:line)
          @token_spacing_cache[:comment_lines] = lines
          lines
        end

        def alignment_aligned_words?(range, line)
          @token_spacing_cache ||= {}
          left_edge = range.column
          if left_edge.positive? && /\s\S/.match?(line[left_edge - 1, 2])
            @token_spacing_cache[:aligned_words] = true
            return true
          end

          token = range.source
          aligned = token == line[left_edge, token.length]
          @token_spacing_cache[:aligned_words] = aligned
          aligned
        end

        def alignment_aligned_identical?(range, line)
          @token_spacing_cache ||= {}
          identical = range.source == line[range.column, range.size]
          @token_spacing_cache[:aligned_identical] = identical
          identical
        end

        def alignment_aligned_with_preceding_assignment_token?(range, token)
          @token_spacing_cache ||= {}
          unless token
            @token_spacing_cache[:preceding_assignment] = false
            return false
          end

          aligned = range.source[-1] == '=' && range.last_column == token.pos.last_column
          @token_spacing_cache[:preceding_assignment] = aligned
          aligned
        end

        def alignment_aligned_with_append_operator?(range, token)
          @token_spacing_cache ||= {}
          unless token
            @token_spacing_cache[:append_operator] = false
            return false
          end

          append_match = ((range.source == '<<' && token.equal_sign?) ||
            (range.source[-1] == '=' && token.type == :tLSHFT)) &&
            range.last_column == token.pos.last_column
          @token_spacing_cache[:append_operator] = append_match
          append_match
        end

        def alignment_aligned_assignment?(range, lineno, processed_source)
          @token_spacing_cache ||= {}
          line_range = processed_source.buffer.line_range(lineno)
          unless line_range
            @token_spacing_cache[:aligned_assignment] = false
            return false
          end

          assignment_token = processed_source.tokens_within(line_range).detect do |token|
            token.equal_sign? || token.type == :tLSHFT

